plan = "Plan:\n- Iterate through each context document.\n- Ask a sub-LLM to identify any singer who fits all constraints:\n  (1) Released an album between 2010–2012 whose title was inspired by a phrase one of their parents used to say.\n  (2) Experienced a tragic event with a loved one between 2009–2022.\n  (3) Released an album between 2015–2023 that includes a song title significant to the tragic event.\n  (4) For that later album, the singer received three award nominations and also won an award for a music video featuring another artist who is the youngest child and visually impaired.\n- Collect per-document candidates with quoted evidence and extracted key fields (loved one's first name).\n- Feed the collected findings to a sub-LLM to decide on the best-supported answer.\n- Return only the loved one’s first name as the final result."
extractions = ()
for d in context:
    q = "You are given a document. Find any singer in the document who satisfies ALL of the following, and extract the detailed evidence:\nConstraints:\n1) They released an album between 2010 and 2012 (inclusive) whose title was inspired by a phrase that one of their parents used to say.\n2) They experienced a tragic event involving a loved one between 2009 and 2022 (inclusive). Extract the loved one's first name.\n3) Between 2015 and 2023 (inclusive), an album was released that includes a song title that holds significance to the tragic event (e.g., named after the person, age, or directly referencing the event). Provide that album and song title(s), and explain the significance.\n4) For that later album, the singer received three award nominations, and also WON an award for a music video featuring another artist who is the youngest child and is visually impaired. Identify the featured artist, confirm they are the youngest child and visually impaired, and provide the award name/year.\nInstructions:\n- If the document contains such a singer, output:\n  Singer: <name>\n  Parent-phrase album (2010–2012): <title, year, the parent phrase and which parent>\n  Tragic event (2009–2022): <what happened, year, loved one's first name>\n  Later album (2015–2023): <title, year>\n  Significant song(s): <title(s) and why they are significant to the tragic event>\n  Awards: <the three nominations for the later album (list them), and the award WON for a music video; include award show name and year>\n  Featured artist in winning video: <name> (confirm: youngest child? visually impaired?)\n  Quotes: <verbatim lines from the document that substantiate each of the above items>\n- If the document does not fully satisfy all constraints, but partially matches, still extract as much as possible and clearly indicate which constraints are missing.\n- If no relevant information, output: No match."
    r = llm_query("BEGIN_DOCUMENT\n" + d + "\nEND_DOCUMENT\n" + q)
    extractions = extractions + (r,)

synthesis_prompt = "You will be given extractions from multiple documents about a query.\nGoal: Identify the singer who fits ALL constraints and return ONLY the first name of the loved one involved in the tragic event.\nConstraints recap:\n- Album released 2010–2012 with title inspired by a phrase one of their parents used to say.\n- A tragic event involving a loved one between 2009–2022; we need that loved one's first name.\n- Between 2015–2023, an album includes a song title significant to the tragic event.\n- For that later album, the singer received three award nominations and also WON an award for a music video featuring another artist who is the youngest child and visually impaired.\nInstructions:\n- Use the extractions and their quotes to verify all constraints. If multiple candidates exist, choose the one that satisfies all constraints with the strongest, explicit evidence.\n- Output ONLY the loved one’s first name, nothing else.\nHere are the extractions:\n" + "\n\n-----\n\n".join(extractions)
final_answer = llm_query(synthesis_prompt)
return_result(final_answer.strip())